  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥1/10) ; fréquent (≥1/100,', 'Fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Au moment de la prescription, les patients doivent être informés des signes et symptômes et doivent faire l’objet d’une surveillance étroite pour détecter ces réactions cutanées.']);

  -- piribedil (CIS 62551633)
