  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Dyskinésie :', 'A un stade avancé de la maladie de Parkinson, en association avec la lévodopa, des dyskinésies peuvent survenir pendant l’initiation du traitement par piribedil.', 'Dans ce cas, la dose de piribedil doit être réduite.', 'Hypotension orthostatique :', 'Les agonistes dopaminergiques sont connus pour altérer la régulation systémique de la pression artérielle conduisant à une hypotension orthostatique posturale.', 'Il est recommandé de surveiller la pression artérielle, en particulier au début du traitement, étant donné le risque d’hypotension orthostatique associé à un traitement dopaminergique.', 'Comportement anormal :', 'Un comportement anormal a été rapporté et peut être associé à des manifestations comprenant confusion, agitation, agressivité.', 'Une diminution de la dose ou un arrêt progressif du traitement doivent être envisagés si de tels symptômes apparaissent.', 'Troubles du sommeil', 'Une somnolence et des accès de sommeil d’apparition soudaine ont été rapportés lors du traitement par piribédil particulièrement chez les patients atteints de maladie de Parkinson.', 'Un endormissement soudain pendant les activités quotidiennes, dans certains cas sans prodromes, a été très rarement rapporté.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Neuroleptiques antiémétiques', 'Antagonisme réciproque entre le dopaminergique et le neuroleptique.', 'Utiliser un antiémétique dénué d’effets extrapyramidaux.', 'Associations déconseillées', 'Neuroleptiques antipsychotiques (sauf clozapine)', 'Antagonisme réciproque du dopaminergique et des neuroleptiques.', 'Le dopaminergique peut provoquer ou aggraver les troubles psychotiques.', 'Tétrabénazine', 'Antagonisme réciproque entre le dopaminergique et la tétrabénazine.', 'Consommation d’alcool', 'Majoration par l’alcool de l’effet sédatif du piribédil.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent (≥1/10) ; fréquent (≥1/100, Les manifestations suivantes peuvent survenir :', 'Fréquent : des troubles psychiques tels que confusion, agitation ou hallucinations (visuelles, auditives, mixtes),ont été observés.', 'Fréquent : des sensations vertigineuses ont été notées, disparaissant à l’arrêt du traitement,']);
