  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les événements indésirables sont classés par ordre décroissant de fréquence, selon la convention suivante : très fréquent (≥ 1/10) ; fréquent (≥ 1/100 à Les effets indésirables rapportés sont les suiv', 'Fréquent : vomissements, nausées, douleurs abdominales hautes, sécheresse de la bouche.', 'Peu fréquent : palpitations.', 'Fréquent : bouffée de chaleur, aggravation d''une affection vasculaire périphérique comme une claudication intermittente existante, ou un syndrome de Raynaud (voir rubriques 4.3 et 4.4).', 'Peu fréquent : hypotension, refroidissement des extrémités.', 'Fréquent: tremblements, paresthésie, céphalées, asthénie, somnolence, sensations vertigineuses.']);
